package ug.audiocity.studio;
import java.nio.*;import java.nio.file.*;import java.util.*;
/** Optional private fixtures supplied as 48 kHz stereo float PCM paths; recordings are never bundled. */
public final class RealVocalTests {
 static int checks;static void check(boolean c,String m){if(!c)throw new AssertionError(m);checks++;}
 public static void main(String[] paths)throws Exception{if(paths.length==0)throw new IllegalArgumentException("Pass external 48 kHz stereo float PCM fixtures");for(String path:paths){FloatBuffer f=ByteBuffer.wrap(Files.readAllBytes(Paths.get(path))).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();float[] source=new float[f.remaining()];f.get(source);float[] tuned=new float[source.length];int[] at={0};PitchCorrector.Config config=new PitchCorrector.Config();config.retuneMs=0;PitchCorrector.Report report=PitchCorrector.correct(new Core.Memory(source),config,(l,r)->{tuned[at[0]++]=l;tuned[at[0]++]=r;});check(at[0]==source.length,"Exact fixture duration");boolean finite=true;double peakIn=0,peakOut=0;for(int i=0;i<source.length;i++){finite&=Float.isFinite(tuned[i]);peakIn=Math.max(peakIn,Math.abs(source[i]));peakOut=Math.max(peakOut,Math.abs(tuned[i]));}check(finite,"All output samples are finite");check(peakOut<peakIn*1.25,"No new large peak overshoot");check(report.voiced>report.analysed*.4,"Reliable pitch detected over substantial vocal material");ArrayList<Double> ratios=new ArrayList<>();for(int pos=0;pos+960<source.length/2;pos+=480){double dry=0,wet=0;for(int i=0;i<960;i++){double x=source[(pos+i)*2],y=tuned[(pos+i)*2];dry+=x*x;wet+=y*y;}if(dry/960>.03*.03)ratios.add(Math.sqrt(wet/dry));}Collections.sort(ratios);double p5=ratios.get((int)(ratios.size()*.05));check(p5>.93,"No repeated dry/wet cancellation: fifth percentile 20 ms RMS ratio above .93 for supplied fixtures");check(ratios.get(0)>.45,"No deep vowel dropout below .45 RMS ratio in supplied fixtures");System.out.println("Real vocal fixture: "+source.length/2+" frames, RMS p5="+p5+", minimum="+ratios.get(0));}System.out.println(checks+" real-vocal fixture checks passed.");}
}
